const descriptions={control:['Sistema di controllo','Coordina i nodi e monitora il funzionamento complessivo del cluster.'],cpu:['Nodo di calcolo','Una macchina autonoma con CPU, RAM e sistema operativo: esegue i processi assegnati.'],gpu:['Nodo con acceleratori','Può integrare GPU per carichi intensivi, come simulazioni e addestramento di modelli.'],storage:['Storage','Conserva programmi, dati e risultati. Può essere condiviso oppure distribuito.']};
document.querySelectorAll('[data-node]').forEach(node=>node.addEventListener('click',()=>{document.querySelectorAll('[data-node]').forEach(n=>{n.classList.remove('selected');n.setAttribute('aria-pressed','false')});node.classList.add('selected');node.setAttribute('aria-pressed','true');const [title,description]=descriptions[node.dataset.node];document.getElementById('node-title').textContent=title;document.getElementById('node-text').textContent=description}));
const progress=document.querySelector('.progress');function updateProgress(){const height=document.documentElement.scrollHeight-innerHeight;progress.style.width=(height>0?scrollY/height*100:0)+'%'}addEventListener('scroll',updateProgress,{passive:true});addEventListener('resize',updateProgress);updateProgress();
